CREATE EXTENSION IF NOT EXISTS vector;
CREATE SCHEMA analytics;
CREATE SCHEMA rag;
CREATE ROLE analytics_reader LOGIN PASSWORD 'local-reader-demo' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT CONNECTION LIMIT 5;
CREATE ROLE rag_writer LOGIN PASSWORD 'local-rag-demo' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT CONNECTION LIMIT 5;
REVOKE ALL ON DATABASE dialogo FROM PUBLIC;
GRANT CONNECT ON DATABASE dialogo TO analytics_reader,rag_writer;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA analytics TO analytics_reader;
GRANT USAGE ON SCHEMA rag TO rag_writer;
ALTER ROLE analytics_reader SET default_transaction_read_only=on;
ALTER ROLE analytics_reader SET statement_timeout='2500ms';
ALTER ROLE analytics_reader SET search_path=analytics,pg_catalog;
CREATE TABLE analytics.dim_province(code text,province text PRIMARY KEY,region text,latitude double precision,longitude double precision);
CREATE TABLE analytics.dim_date(date date PRIMARY KEY,year int,month int,quarter int);
CREATE TABLE analytics.fact_hotel(province text REFERENCES analytics.dim_province(province),period_start date,year int,travelers_total double precision,travelers_domestic double precision,travelers_foreign double precision,nights_total double precision,nights_domestic double precision,nights_foreign double precision,occupancy_pct double precision,hotel_beds double precision,hotels double precision,mean_stay double precision,PRIMARY KEY(province,period_start));
CREATE TABLE analytics.fact_markets_annual(region text,country text,year int,spend_eur double precision,spend_per_person_eur double precision,daily_spend_eur double precision,mean_trip_days double precision,PRIMARY KEY(region,country,year));
CREATE TABLE analytics.fact_region_monthly(region text,period_start date,year int,international_tourists double precision,spend_eur double precision,spend_per_person_eur double precision,daily_spend_eur double precision,mean_trip_days double precision,PRIMARY KEY(region,period_start));
CREATE TABLE analytics.fact_housing(province text REFERENCES analytics.dim_province(province),period_start date,year int,homes double precision,beds double precision,beds_per_home double precision,PRIMARY KEY(province,period_start));
CREATE TABLE analytics.fact_forecast(province text REFERENCES analytics.dim_province(province),period_start date,predicted_nights bigint,lower bigint,upper bigint,model text,input_last_month date,PRIMARY KEY(province,period_start));
GRANT SELECT ON ALL TABLES IN SCHEMA analytics TO analytics_reader;
CREATE TABLE rag.schema_embeddings(id uuid PRIMARY KEY,content text,metadata jsonb,embedding vector(768));
CREATE INDEX schema_embeddings_cosine ON rag.schema_embeddings USING hnsw(embedding vector_cosine_ops);
GRANT SELECT,INSERT,UPDATE,DELETE ON rag.schema_embeddings TO rag_writer;
